sys_script_include.script:
var CallbackRecordCreation = Class.create();
CallbackRecordCreation.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    executeCallbackSubflow: function() {
        gs.info('[CALLBACK SERVER LOG] Running subflow execution script via Email Toolkit handoff.');

        try {
            // 1. Gather fields safely passed over from the workspace modal payload
            var reason        = this.getParameter('sysparm_reason');
            var details       = this.getParameter('sysparm_details');
            var phone         = this.getParameter('sysparm_phone');
            var contextCase   = this.getParameter('sysparm_context');
            var interactionId = this.getParameter('sysparm_interaction');

            gs.info('[CALLBACK SERVER LOG] Subflow parameters verified -> Interaction: ' + interactionId + ' | Context: ' + contextCase);

            // 2. Map fields to exactly match your Flow Designer Subflow schema inputs
            var inputs = {};
            inputs['callback_context']    = contextCase; 
            inputs['interaction_sys_id']  = interactionId; 
            inputs['callback_number']     = phone; 
            inputs['callback_reason']     = details; 
            inputs['reason_for_the_call'] = reason; 

            gs.info('[CALLBACK SERVER LOG] Triggering Flow Runner Engine for: x_snc_pab_ee_tkit.create_a_callback_activity');

            // 3. Execute Synchronously inside the foreground pipeline block
            var result = sn_fd.FlowAPI.getRunner()
                .subflow('x_snc_pab_ee_tkit.create_a_callback_activity')
                .inForeground()
                .withInputs(inputs)
                .run();

            var outputs = result.getOutputs();
            var callback_activity_notes = outputs['callback_activity_notes'] || '';

            gs.info('[CALLBACK SERVER LOG] Execution complete. Subflow output notes: ' + callback_activity_notes);

            return JSON.stringify({ 
                status: 'success', 
                notes: callback_activity_notes 
            });

        } catch (ex) {
            var message = ex.getMessage ? ex.getMessage() : ex.message;
            gs.error('[CALLBACK SERVER ERROR] Fatal subflow execution exception: ' + message);
            return JSON.stringify({ status: 'error', message: message });
        }
    },

    type: 'CallbackRecordCreation'
});
